UPDATE telegram_conversations
SET current_step = 'awaiting_category_filter'
WHERE id = {{ $('Resolve Conversation').item.json.id }};

WITH primeiro AS (
  SELECT MIN(expense_date) AS primeira_data
  FROM expenses_bot_telegram
  WHERE user_id = {{ $('Resolve Conversation').item.json.user_id }}
    AND category_id = {{ $json.id }}
),
meses AS (
  SELECT GREATEST(
    1,
    ((EXTRACT(YEAR FROM age(date_trunc('month', CURRENT_DATE), date_trunc('month', COALESCE(primeira_data, CURRENT_DATE)))) * 12)
     + EXTRACT(MONTH FROM age(date_trunc('month', CURRENT_DATE), date_trunc('month', COALESCE(primeira_data, CURRENT_DATE)))) + 1)::int
  ) AS qtd_meses
  FROM primeiro
)
SELECT
  COALESCE(SUM(e.amount) FILTER (WHERE e.expense_date >= date_trunc('month', CURRENT_DATE)), 0) AS total_mes_atual,
  COALESCE(SUM(e.amount) FILTER (WHERE e.expense_date >= date_trunc('month', CURRENT_DATE) - interval '3 months'), 0)
    / LEAST(3, m.qtd_meses) AS media_3_meses,
  COALESCE(SUM(e.amount) FILTER (WHERE e.expense_date >= date_trunc('month', CURRENT_DATE) - interval '12 months'), 0)
    / LEAST(12, m.qtd_meses) AS media_1_ano
FROM meses m
LEFT JOIN expenses_bot_telegram e
  ON e.user_id = {{ $('Resolve Conversation').item.json.user_id }}
  AND e.category_id = {{ $json.id }}
GROUP BY m.qtd_meses;

