const totais = $input.first().json; // troque 'Node B' pelo nome real do node da query de totais
const categoria = $('Valid if the Category Belongs User').first().json.name

const total_mes = Number(totais.total_mes_atual);
const media_3 = Number(totais.media_3_meses);
const media_ano = Number(totais.media_1_ano);

const variacao = media_3 > 0 ? ((total_mes - media_3) / media_3 * 100) : null;
const seta = variacao === null ? '' : (variacao >= 0 ? `📈 +${variacao.toFixed(0)}%` : `📉 ${variacao.toFixed(0)}%`);

const texto = `📂 ${categoria}\n\n` +
  `Este mês: R$ ${total_mes.toFixed(2)} ${seta ? `(${seta} vs média de 3 meses)` : ''}\n` +
  `Média (últimos 3 meses): R$ ${media_3.toFixed(2)}\n` +
  `Média (últimos 12 meses): R$ ${media_ano.toFixed(2)}`;

return [{ json: { text: texto } }];

const totais = $('Get Mounth Expenses').first().json;
const data = $input.all().map(i => i.json); 

const total = Number(totais.total_periodo);
const anterior = Number(totais.total_anterior);
const variacao = anterior > 0 ? ((total - anterior) / anterior * 100) : null;
const seta = variacao === null ? '' : (variacao >= 0 ? `📈 +${variacao.toFixed(0)}%` : `📉 ${variacao.toFixed(0)}%`);

const linhas = data.map(c => {
  const pct = total > 0 ? (Number(c.total) / total * 100).toFixed(0) : 0;
  return `- ${c.categoria}: R$ ${Number(c.total).toFixed(2)} (${pct}%)`;
}).join('\n');

const texto = `Total: R$ ${total.toFixed(2)} ${seta ? `vs mês anterior (${seta})` : ''}\n\n${linhas || 'Nenhum gasto nesse período.'}`;

return [{ json: { text: texto } }];

