    },
    "date_ref": {
      "type": ["string", "null"],
      "enum": ["today", "yesterday", "day_before_yesterday", "weekday", "explicit", null],
      "description": "Type of date reference, or null if no date was mentioned"
    },
    "weekday": {
      "type": ["integer", "null"],
      "minimum": 1,
      "maximum": 7,
      "description": "1=Monday ... 7=Sunday, only when date_ref is weekday"
    },
    "week_qualifier": {
      "type": ["string", "null"],
      "enum": ["last", "none", "next", null],
      "description": "last for 'passada', next for 'próxima', otherwise none"
    },
    "explicit_date": {
      "type": ["string", "null"],
      "description": "YYYY-MM-DD only if a full date was stated, else null"
    }
  },
  "required": ["amount", "description", "date_ref", "weekday", "week_qualifier", "explicit_date"],
  "additionalProperties": false
}

parameters.jsCode:
const o = $input.first().json.output;
const today = DateTime.now().setZone('America/Sao_Paulo').startOf('day');

let date = today;

switch (o.date_ref) {
    case 'yesterday': date = today.minus({ days: 1 });
    break;
  case 'day_before_yesterday': date = today.minus({ days: 2 }); break;
  case 'explicit': date = DateTime.fromISO(o.explicit_date, { zone: 'America/Sao_Paulo' }); break;
  case 'weekday': {
    const back = (today.weekday - o.weekday + 7) % 7;

    if (o.week_qualifier === 'next') date = today.plus({ days: (o.weekday - today.weekday + 7) % 7 || 7 });
    else if (o.week_qualifier === 'last') date = today.minus({ days: back || 7 });
    else date = today.minus({ days: back });
  }
}

const ok = date.isValid && (o.amount === null || o.amount > 0);

return [{ json: { ...o, date: date.isValid ? date.toISODate() : null, input_ok: ok } }];

